xt":"Add the stock a ladle at a time, stirring, for 18 min.","timer":{"label":"Cooking","min":18}},{"text":"Off the heat, add the mushrooms, the rest of the butter and the parmesan.","timer":null}]},{"title":"Chicken biryani","intro":"The spiced Indian rice dish cooked with chicken marinated in yoghurt.","minutes":75,"calories":560,"difficulty":"Moyen","imageSearch":"chicken biryani","veg":false,"oven":false,"cold":false,"missing":"","origin":"Indian recipe","serves":4,"items":[{"name":"basmati rice","plural":"basmati rice","qty":300,"unit":"g","have":false},{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"turmeric","plural":"turmeric","qty":1,"unit":"tsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken into pieces and marinate for 30 minutes with the yoghurt and the spices.","timer":{"label":"Rest","min":30}},{"text":"Brown the sliced onions in a casserole dish, then take out half of them.","timer":{"label":"Cooking","min":10}},{"text":"Add the chicken and its marinade and cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Cover with the rinsed rice and 55 cl of water, without stirring.","timer":null},{"text":"Cover and cook for 20 minutes over a low heat.","timer":{"label":"Cooking","min":20}},{"text":"Sprinkle with the reserved onions and coriander.","timer":null}]},{"title":"Pork nems","intro":"Crispy fried rolls filled with pork, vermicelli and wood ear mushrooms.","minutes":60,"calories":350,"difficulty":"Difficile","imageSearch":"vietnamese spring rolls nem","veg":false,"oven":false,"cold":false,"missing":"","origin":"Vietnamese r