":"Frying","min":4}}],"makes":{"n":16,"one":"arancini","many":"arancini"}},{"title":"Sausage rougail","intro":"The dish from Réunion: smoked sausages simmered in a tomato sauce with ginger and chilli.","minutes":50,"calories":620,"difficulty":"Facile","imageSearch":"rougail saucisse","veg":false,"oven":false,"cold":false,"missing":"","origin":"Réunion recipe","serves":4,"items":[{"name":"smoked sausage","plural":"smoked sausages","qty":6,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":6,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"turmeric","plural":"turmeric","qty":1,"unit":"tsp","have":false},{"name":"chilli","plural":"chillies","qty":1,"unit":"","have":false},{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false}],"steps":[{"text":"Blanch the sausages in boiling water for 5 minutes, then slice them.","timer":{"label":"Cooking","min":5}},{"text":"Brown them in a casserole dish.","timer":null},{"text":"Add the sliced onions, garlic, ginger, turmeric and chilli.","timer":null},{"text":"Add the diced tomatoes and simmer for 25 minutes.","timer":{"label":"Simmer","min":25}},{"text":"Serve with white rice.","timer":null}]},{"title":"Tandoori chicken","intro":"Chicken thighs marinated in yoghurt and tandoori spices, then roasted in the oven.","minutes":60,"calories":420,"difficulty":"Facile","imageSearch":"tandoori chicken","veg":false,"oven":true,"cold":false,"missing":"","origin":"Indian dish","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":2,"unit":"","have":false},{"name":"tandoori spice mix","plural":"tandoori spice mix","qty":2,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"garli