chopped peppers and onion for 4 minutes, then add the pineapple.","timer":{"label":"Wok","min":4}},{"text":"Pour in the sauce, let it thicken for 2 minutes and add the chicken. Serve with rice.","timer":{"label":"Wok","min":2}}],"kids":true},{"title":"Chilli con carne","intro":"Minced beef, kidney beans and tomatoes, spiced with cumin and chilli.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"chili con carne","veg":false,"oven":false,"cold":false,"missing":"","origin":"Tex-Mex dish","serves":4,"items":[{"name":"minced beef","plural":"minced beef","qty":500,"unit":"g","have":false},{"name":"kidney bean","plural":"kidney beans","qty":400,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"cumin","plural":"cumin","qty":2,"unit":"tsp","have":false},{"name":"chilli powder","plural":"chilli powder","qty":0.5,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onions, diced pepper and garlic in the oil for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the meat and spices, and brown for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the tomatoes, season with salt and simmer for 25 minutes.","timer":{"label":"Simmer","min":25}},{"text":"Add the drained kidney beans and cook for 10 minutes. Serve with rice.","timer":{"label":"Cooking","min":10}}],"kids":true},{"title":"Beef empanadas","intro":"Golden Argentinian turnovers filled with beef, onions and paprika.","minutes":60,"calories":380,"difficulty":"Moyen","imageSearch":"beef empanadas","veg":false,"oven":true,"cold":false,"missing":"","origin":"Argentinian recipe","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":2,"unit":"","have":false},{"name":"minced beef","plural":"minced beef","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":2,"unit":"tsp","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false}],"steps":[{"text":"Fry the diced onions and pepper, then add the beef and spices and cook for 8 min.","timer":{"label":"Pan","min":8}},{"text":"Hard-boil an egg for 10 min, chop it and add it to the filling.","timer":{"label":"Cooking","min":10}},{"text":"Preheat the oven to 200 °C. Cut 12 cm circles from the pastry.","timer":null},{"text":"Spoon the filling onto half of each circle, fold over and press the edges closed with a fork.","timer":null},{"text":"Brush with the second beaten egg and bake for 20 min.","timer":{"label":"Oven","min":20}}],"makes":{"n":12,"one":"empanada","many":"empanadas"}},{"title":"Piperade","intro":"The soft peppers and tomatoes of the Basque Country, with Bayonne ham.","minutes":45,"calories":280,"difficulty":"Facile","imageSearch":"piperade basque","veg":false,"oven":false,"cold":false,"missing":"","origin":"Basque speciality","serves":4,"items":[{"name":"green pepper","plural":"green peppers","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":5,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"bayonne ham","plural":"bayonne ham","qty":4,"unit":"slices","have":false},{"name":"espelette pepper","plural":"espelette pepper","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Slice the onions and the peppers, and dice the tomatoes.","timer":null},{"text":"Soften the onions and the peppers for 15 minutes in the oil.","timer":{"label":"Pan","min":15}},{"text":"Add the tomatoes, the garlic and the espelette pepper, and leave for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Fry the ham for a few seconds in a pan and lay it on the piperade.","timer":null}]},{"title":"Shakshuka","intro":"Poached eggs in a tomato and pepper sauce with cumin and paprika.","minutes":30,"calories":320,"difficulty":"Facile","imageSearch":"shakshuka eggs tomato","veg":true,"oven":false,"cold":false,"missing":"","origin":"North African dish","serves":4,"items":[{"name":"egg","plural":"eggs","qty":6,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and the pepper strips in the oil for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Add the garlic, spices and tomatoes, season with salt and simmer for 10 minutes.","timer":{"label":"Simmer","min":10}},{"text":"Make small wells and crack an egg into each one.","timer":null},{"text":"Cover and cook for 6 minutes, until the whites are set.","timer":{"label":"Cooking","min":6}},{"text":"Sprinkle with coriander and serve with bread.","timer":null}]},{"title":"Tuna rice salad","intro":"Cold rice with tuna, tomatoes, sweetcorn, pepper and hard-boiled eggs.","minutes":30,"calories":450,"difficulty":"Facile","imageSearch":"rice salad tuna","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false},{"name":"tuna in brine","plural":"tuna in brine","qty":280,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":140,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"oil","plural":"oil","qty":3,"unit":"tbsp","have":false},{"name":"vinegar","plural":"vinegar","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the rice, then rinse it under cold water.","timer":{"label":"Cooking","min":12}},{"text":"Boil the eggs for 10 minutes and cut into quarters.","timer":{"label":"Cooking","min":10}},{"text":"Dice the tomatoes and pepper, and flake the tuna.","timer":null},{"text":"Toss everything with the sweetcorn, oil and vinegar, then season with salt and pepper.","timer":null}],"kids":true},{"title":"Ratatouille","intro":"Sun-ripened vegetables slowly simmered in olive oil and herbes de Provence.","minutes":75,"calories":220,"difficulty":"Facile","imageSearch":"ratatouille provencal vegetables","veg":true,"oven":false,"cold":false,"missing":"","origin":"Niçoise speciality","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"yellow pepper","plural":"yellow peppers","qty":1,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qt