 oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken and onions in the oil in a large pot.","timer":null},{"text":"Add the spices, tomatoes, and the carrots and turnips in chunks, then 1.5 l of water. Simmer for 40 minutes.","timer":{"label":"Simmer","min":40}},{"text":"Add the courgettes and chickpeas and cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Grill the merguez for 10 minutes.","timer":{"label":"Grill","min":10}},{"text":"Pour over the same volume of boiling salted water as couscous, cover for 5 minutes, then fluff with the butter. Serve with the broth, vegetables and meats.","timer":{"label":"Rest","min":5}}],"kids":true},{"title":"Spaghetti bolognese","intro":"A slow-simmered meat and tomato sauce on al dente spaghetti.","minutes":50,"calories":620,"difficulty":"Facile","imageSearch":"spaghetti bolognese","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"minced beef","plural":"minced beef","qty":400,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"oregano","plural":"oregano","qty":null,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion, the diced carrot 