insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:epinard', 'spinach', array['en:spinach']::text[], 'list', $r$[{"title":"Creamed spinach","intro":"Spinach cooked down in cream and nutmeg, to serve as a side.","minutes":15,"calories":150,"difficulty":"Facile","imageSearch":"creamed spinach","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"baby spinach","plural":"baby spinach","qty":600,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":15,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false}],"steps":[{"text":"Melt the chopped garlic in the butter.","timer":null},{"text":"Add the spinach a handful at a time and let it wilt for 3 min.","timer":{"label":"Pan","min":3}},{"text":"Add the cream and the nutmeg.","timer":null},{"text":"Let it reduce for 3 min, then add salt and pepper.","timer":{"label":"Cooking","min":3}}],"kids":true},{"title":"Spinach and ricotta cannelloni","intro":"Pasta tubes stuffed with ricotta and spinach, baked in tomato sauce.","minutes":60,"calories":520,"difficulty":"Moyen","imageSearch":"spinach ricotta cannelloni","veg":true,"oven":true,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"cannelloni tube","plural":"cannelloni tubes","qty":16,"unit":"","have":false},{"name":"ricotta","plural":"ricotta","qty":500,"unit":"g","have":false},{"name":"frozen spinach","plural":"frozen spinach","qty":400,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":600,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarella","qty":1,"unit":"","have":false},{"name":"parmesan","plural":"parmesan","qty":50,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Defrost the spinach and squeeze it dry.","timer":null},{"text":"Mix it with the ricotta, the egg, half of the parmesan, salt and pepper.","timer":null},{"text":"Fill the cannelloni using a piping bag or a small spoon.","timer":null},{"text":"Spread half of the tomatoes in a dish, arrange the cannelloni on top and cover with the rest.","timer":null},{"text":"Add the mozzarella and the parmesan, and bake for 35 minutes.","timer":{"label":"Oven","min":35}}],"makes":{"n":16,"one":"cannelloni","many":"cannelloni"}},{"title":"Bibimbap","intro":"The Korean bowl: rice, marinated beef, stir-fried vegetables, a fried egg and chilli sauce.","minutes":45,"calories":580,"difficulty":"Moyen","imageSearch":"bibimbap","veg":false,"oven":false,"cold":false,"missing":"","origin":"Korean recipe","serves":4,"items":[{"name":"rice","plural":"rice","qty":300,"unit":"g","have":false},{"name":"minced beef","plural":"minced beef","qty":300,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"korean chilli paste","plural":"korean chilli paste","qty":2,"unit":"tbsp","have":false},{"name":"sesame oil","plural":"sesame oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the beef with 2 tbsp of soy sauce and 1 tbsp of sesame oil.","timer":{"label":"Pan","min":6}},{"text":"Stir-fry the carrots and courgette sticks separately, then the spinach.","timer":{"label":"Pan","min":8}},{"text":"Fry the eggs.","timer":{"label":"Pan","min":4}},{"text":"Put the rice in bowls, arrange the vegetables and the beef in sections, and top with the egg.","timer":null},{"te