,"serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":500,"unit":"g","have":false},{"name":"baby spinach","plural":"baby spinach","qty":100,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and garlic in the oil with the spices for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Add the tomatoes and simmer for 10 minutes.","timer":{"label":"Simmer","min":10}},{"text":"Add the chickpeas, cream and spinach, and cook for 5 minutes.","timer":{"label":"Cooking","min":5}}]},{"title":"Green smoothie","intro":"A fresh, vitamin-packed smoothie, all green.","minutes":5,"calories":140,"difficulty":"Facile","imageSearch":"green smoothie","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"baby spinach","plural":"baby spinach","qty":60,"unit":"g","have":false},{"name":"kiwi","plural":"kiwis","qty":2,"unit":"","have":false},{"name":"apple","plural":"apples","qty":1,"unit":"","have":false},{"name":"banana","plural":"bananas","qty":1,"unit":"","have":false},{"name":"orange juice","plural":"orange juice","qty":30,"unit":"cl","have":false}],"steps":[{"text":"Peel the kiwis and the banana, and cut up the apple.","timer":null},{"text":"Put everything in the blender with the spinach and the orange juice.","timer":null},{"text":"Blend until smooth.","timer":null},{"text":"Serve straight away.","timer":null}],"dessert":true},{"title":"Vegetarian calzone","intro":"A soft calzone with spinach and r